/**
 * 앱 리스트 조회 (reactive - 스토리지 기반)
 * @param {number} limit - 가져올 개수 (기본값: 5)
 * @returns {Object} { appList, fetch }
 */
export const useAppList = (limit = 5) => {
    const appList = ref([])

    const updateList = () => {
        const allApps = commonStorage.get(STORAGE_KEYS.SIDEMENU_APP_LIST) || []
        appList.value = getFormattedAppList(allApps).slice(0, limit)
    }

    // 사이드메뉴 재조회 시 자동 업데이트
    const handleRefresh = () => {
        updateList()
    }

    onMounted(() => {
        updateList()
        bus.on(BUS_EVENT.SIDEMENU_REFRESH, handleRefresh)
    })

    onUnmounted(() => {
        bus.off(BUS_EVENT.SIDEMENU_REFRESH, handleRefresh)
    })

    return {
        appList,
        fetch: updateList,
    }
}
