let toastProxy = null
let customToastManager = null

export const setToastProxy = (proxy) => {
  toastProxy = proxy
}

// 커스텀 토스트 매니저 설정 (App.vue 에서 호출)
export const setCustomToastManager = (manager) => {
  customToastManager = manager
}

export const toast = (msg, options = {}) => {
  const duration = options.duration ?? 2000
  const action = options.action ?? null // { label: '이동하기', onClick: () => {} }

  // action 이 있는 경우 커스텀 토스트 사용
  if (action && customToastManager) {
    customToastManager.add(msg, { duration, action })
    return
  }

  // 일반 토스트 사용
  if (toastProxy?.$toast) {
    toastProxy.$toast(msg, { duration })
  } else {
    console.log('[toast]', msg)
  }
}

